\section{Non-wellfounded systems based on Bellantoni-Cook}
\label{sec:cbc-nucbc}
Throughout this section we shall work with the system $\bcnorec \dfn \bc \setminus \{\saferec\}$.

\begin{defn}[Coderivations]
A ($\bcnorec$-)\emph{coderivation} $\der$ is a possibly infinite {rooted} tree generated by the rules of $\bcnorec$.
Formally, we identify $\der$ with a (labelled) prefix-closed subset of $ \{0,1,2\}^*$ (i.e.\ a ternary tree).
Each node is labelled by an inference step from $\bcnorec$ such that, whenever $\nu\in \der$ is labelled by a step $\vliiinf{}{}{S}{S_1}{\cdots}{S_n}$, for $n\leq 3$, $\nu$ has $n$ children in $\der$ labelled by steps with conclusions $S_1, \dots, S_n$ respectively. 
Sub-coderivations of a coderivation $\der$ rooted at position $\nu \in \{0,1,2 \}^*$ are denoted $\pder\nu$, so that $\pder\epsilon=\der$. 
\end{defn}

\begin{defn}[Semantics of coderivations]
\label{defn:semantics-coderivations}
To each $\bcnorec$-coderivation $\der$ we associate a two-sorted Kleene-Herbrand-G\"odel partial function $\denot \der$ obtained by construing the semantics of \Cref{defn:semantics-bc} as a (possibly infinite) equational program.
Given a two-sorted function $f(\vec x; \vec y)$, we say that $f$ is \emph{defined} by a $\bcnorec$-coderivation $\der$ if $\denot\der(\vec x; \vec y)=f(\vec x; \vec y)$. 
\end{defn}

\begin{defn}[Ancestry]
\label{defn:ancestry}
Fix a coderivation $\der$. We say that a type occurrence $A$ is an \emph{immediate ancestor} of a type occurrence $B$ in $\der$ if they are types in a premiss and conclusion (respectively) of an inference step and, as typeset in \Cref{fig:bc-type-system}, have the same colour.
If $A$ and $B$ are in some $\orange \Gamma$ or $\purple{ \Gamma'}$, then furthermore they must be in the same position in the list.
\end{defn}

\begin{defn}[Progressing coderivations]
\label{defn:progressing}
Fix a coderivation $\der$. A \emph{thread} is a maximal path in the graph of immediate ancestry.
We say that a (infinite) thread is \emph{progressing} if it is eventually constant $\sn$ and infinitely often principal for a $\cnd_{\sq}$ rule or a $\cndl_\sq$ rule. A coderivation is \emph{progressing} if each of its infinite branches has a progressing thread.
\end{defn}

\begin{defn}[Safety, left-leaning]\label{defn:conditions} We say that a coderivation $\der$ is  \emph{safe} if each  branch crosses only finitely many $\cut_\sq$-steps, and  \emph{left-leaning} if each  branch goes right at a $\cut_\n$-step only finitely often.
\end{defn}

\begin{defn}[Generalised regularity]
\label{defn:regularity}
\Achange{Let $\mathsf R\subseteq \bcnorec$.
A $\bcnorec$-coderivation $\der$ is \emph{$\mathsf R$-regular} if it has only finitely many distinct sub-coderivations containing rules among $\mathsf R$. 
If $\mathsf R = \bcnorec$,} i.e.~it has only finitely many distinct sub-coderivations, then we say that $\der$ is \emph{regular} \Achange{(or \emph{circular})}. 
\end{defn}

\begin{defn}[$\cbc$ and $\nucbc$]\label{defn:non-wellfounded-proof-systems}
$\cbc$ is the class of regular progressing safe and left-leaning $\bcnorec$-coderivations. $\nucbc$ is the class of $\relaxed$-regular progressing safe and left-leaning $\bcnorec$-coderivations. A two-sorted function $f(\vec x;\vec y)$ is  \emph{$\cbc$-definable} (resp.~\emph{$\nucbc$-definable}) if there is a coderivation $\der \in \cbc$  (resp.~$\der \in \nucbc$ ) such that $\denot \der (\vec x;\vec y) = f(\vec x;\vec y)$. 
\end{defn}

