\section{Proof of~\Cref{lem:rel-tran-lem}}

\begin{defn}[Cycle normal form]
\black{Let $F$ be a set of  two-sorted functions, and let $\der$ be a regular $\bcnorec(F)$-coderivation. }
The  \emph{cycle normal form} (or simply \emph{cycle nf}) of $\der$ is a pair $\derrd$, where  $\rd$ is a partial self-mapping on the nodes of $\der$ whose domain of definition is denoted $\bud(\der)$ and:
\begin{enumerate}[(i)]
    \item every infinite branch of $\der$ contains some (unique) $\nu \in \bud(\der)$;
    \item if $\nu \in \bud(\der)$ then both $\rd(\nu) \sqsubset \nu$ and  $\der_{\rd(\nu)} = \der_\nu$;
    \item for any two distinct nodes $\mu \sqsubset \nu$ strictly below $\bud(\der)$, $\der_\mu \neq \der_\nu$
\end{enumerate}


We call any $\nu \in \bud(\der)$ a \emph{bud}, and $\rd(\nu)$ its \emph{companion}. A \emph{terminal} node is either one of the leaves of $\der$ (\black{among which, the functions in  $F$}) or   a bud. The set of nodes of $\der$ bounded above by a terminal node is denoted $T_\der$.  
Given a node $\nu\in T_\der$, we  define $\bud_\nu(\der)$ as the restriction of buds to those above $\nu$.
\end{defn}

\begin{prop}\label{prop:structureofcycles}
\black{Let $F$ be  two-sorted  functions, and let $\der$ be a regular   $\bcnorec(F)$-coderivation} with cycle nf $\derrd$. 
For any  $\nu \in \bud(\der)$, the (finite) path $\pi$ from $\rd(\nu)$ to $\nu$ satisfies:
\begin{enumerate}
\item \label{enum:budcompanion0} if  $\der$ is progressing, $\pi$ must contain the conclusion of an instance of $\cnd_{\sn}$ \black{or $\cndl_\sq$};
    \item \label{enum:budcompanion1} if  $\der$ is \black{progressing and safe}, $\pi$ cannot  contain  the conclusion of  $\cut_{\sn}$, $\sql$,  $\wk_{\sq}$, and  the   leftmost premise of  $\cnd_{\sq}$ \black{and of $\cndl_{\sq}$};
    \item \label{enum:budcompanion3} if $\der$ is a \black{$\cbc(F)$-coderivation},  $\pi$  cannot contain the conclusion of $\wk_{\n}$, the leftmost premise of  $\cnd_{\n}$ \black{and of $\cndl_{\n}$}, and the rightmost premise of $\cut_{\n}$.
\end{enumerate}
\end{prop}

In what follows we shall indicate circularities in cycle nfs explicitly by extending   \black{$\cbc(F)$} with a new inference rule called $\com$: 
$$
\vlinf{\com}{X}{\Gamma \Rightarrow A}{\Gamma \Rightarrow A}
$$
where $X$ is a finite set of nodes. 
In this presentation, we insist that each companion $\nu$ of the cycle nf $\derrd$ is always the conclusion of an instance of $\com$, where $X$ denotes the set of buds $\nu'$ such that $\rd(\nu')=\nu$.  
This expedient will allow us to formally 
distinguish cases when a node of $T_\der$ is a companion from those where it is the conclusion of a standard rule of $\bcnorec$.

\begin{defn} \black{Let $F$ be a set of   two-sorted  functions, and let}  $\derrd$ be the  cycle normal form of a \black{$\bcnorec(F)$-coderivation} $\der$. We define the following two sets for any $\nu\in T_\der$:
$$
\begin{aligned}
\close{\nu}&\dfn \{ \mu \in \rd(\bud_\nu(\der))  \ \vert \ \nu \sqsubseteq \mu \}\\
\open{\nu}&\dfn \{ \mu \in \bud_\nu(\der)) \ \vert \ \rd(\mu) \sqsubset \nu \}
\end{aligned}
$$
\end{defn}
