It remains to show that~\eqref{eqn:translationintermediate2} and~\eqref{eqn:4} satisfy point~\ref{enum:a}. On the one hand for all $\nu \in \close{\hnu}$ we  have  $h_{\nu}\in \bcpp((\model{\pder{\mu}})_{\mu \in \open{\hnu}}, (a_\mu)_{\mu \in \close{\hnu}}\black{,\safnor R} )$, with   $(a_\mu)_{\mu \in \close{\hnu}} $  oracle functions.  On the other hand, by applying the induction hypothesis, we have  $\model{\pder{\hnu}}=\model{\pder{\nu'}}\in \bcpp((\model{\pder\mu})_{\mu \in \open{\nu'}}\black{, \safnor R})$ and  $\model{\pder{\nu}}\in \bcpp((\model{\pder\mu})_{\mu \in \open{\nu'}}\black{, \safnor R})$, for all $\nu \in \close{\hnu}$.  Since $\open{\nu'}= \open{\hnu}\cup X$ and  $\model{\pder{\hnu}}= \model{\pder{\mu}}$ for all $\mu \in X$, we have both  $\model{\pder{\hnu}}\in \bcpp((\model{\pder\mu})_{\mu \in \open{\hnu}}\black{,  \safnor R})$ and   $\model{\pder{\nu}}\in \bcpp((\model{\pder\mu})_{\mu \in \open{\hnu}},  \model{\pder\hnu}\black{, \safnor R})$ for all $\nu \in \close{\hnu}$, and hence $\model{\pder{\nu}}\in \bcpp((\model{\pder\mu})_{\mu \in \open{\hnu}}\black{, \safnor R})$, for all $\nu \in \close{\hnu}$. 

Last, suppose that $\hnu$ is the conclusion of an instance of $\cut_{\n}$ with premises $\nu_1$ and $\nu_2$ then:
\begin{equation*}
    \model{\pder{\hnu}}(\vec{x}; \vec{y})= \model{\pder{\nu_2}}(\vec{x}; \model{\pder{\nu_1}}(\vec{x}; \vec{y}), \vec{y}) 
\end{equation*}
\black{By Proposition~\ref{prop:structureofcycles}.\ref{enum:budcompanion3} we have $\open{\nu_2}= \emptyset$, so that $\model{\pder{\nu_2}}(\vec{x};y, \vec{y})\in \bcpp(\safnor R)$ by applying the induction hypothesis on $\nu_1$}. We shall only consider the case where $\open{\nu_1}\neq \emptyset$. Then, \black{$\open{\hnu}=\open{\nu_1}$ and  $\close{\hnu}=\close{\nu_1}$}. 
Moreover,  induction hypothesis on $\nu_1$:
      \[
\arraycolsep=2pt
\begin{array}{c}
       \model{\pder{\nu_1}}(\vec{x};\vec{y})  = 
       h_{\nu_1}(( \lambda \vec{u}\subseteq \vec{x}, \black{\vec v\subseteq  \vec y}. \model{\pder{\mu}}(\vec{u};v,\vec v))_{\mu \in \close{\nu_1}\cup \open{\nu_1}})(\vec{x}; \vec{y})
\end{array}
\]
So that:
\begin{equation*}
\model{\pder{\hnu}}(\vec{x}; \vec{y})=h_{\hnu}(( \lambda \vec{u}\subseteq \vec{x}, \black{\lambda \vec v\subseteq \vec y}. \model{\pder{\mu}}(\vec{u};\vec v))_{\mu \in \close{\hnu}\cup \open{\hnu}})(\vec{x}; \vec{y})
\end{equation*}
for some $h_{\hnu}$. Points~\ref{enum:a} and~\ref{enum:b}  hold by applying the induction hypothesis. 
\end{proof}
